-- ============================================================================
-- PHANTOM HQ — جدول معارك الشعبية والتصويت (popularity_matches)
--
-- نفّذ السطر المضغوط التالي كاملاً في Supabase → SQL Editor → Run
-- (نسخة واحدة في سطر واحد، قابلة لإعادة التنفيذ بأمان)
-- ============================================================================

create table if not exists public.popularity_matches (id text primary key, player_a text not null, player_b text not null, status text not null default 'active', votes_a integer not null default 0, votes_b integer not null default 0, voters jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), ended_at timestamptz); alter table public.popularity_matches enable row level security; drop policy if exists "pop_matches_select" on public.popularity_matches; drop policy if exists "pop_matches_insert" on public.popularity_matches; drop policy if exists "pop_matches_update" on public.popularity_matches; drop policy if exists "pop_matches_delete" on public.popularity_matches; create policy "pop_matches_select" on public.popularity_matches for select to anon, authenticated using (true); create policy "pop_matches_insert" on public.popularity_matches for insert to anon, authenticated with check (true); create policy "pop_matches_update" on public.popularity_matches for update to anon, authenticated using (true) with check (true); create policy "pop_matches_delete" on public.popularity_matches for delete to anon, authenticated using (true); do $$ begin if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'popularity_matches') then alter publication supabase_realtime add table public.popularity_matches; end if; end $$;
